const icon=(name,cls='')=>`<svg aria-hidden="true" class="icon ${cls}" viewBox="0 0 24 24"><path d="${icons[name]||icons.sunflower}"/></svg>`;
const TH={sunflower:'向日葵',forest:'森林树影',stars:'星夜'};
const STATUS={queued:'排队中',generating:'构建模型',submitting:'提交 Tripo',polling:'Tripo 生成中',uploading:'上传参考图',downloading:'下载原稿',preparing:'准备制造草案',configuration_failed:'生成配置不可用',upload_failed:'参考图上传失败',poll_failed:'查询暂不可用',download_failed:'原稿下载失败',preparation_failed:'草案准备失败',needs_review:'待人工检查',reviewed:'已留检查记录',failed:'任务失败',submission_unknown:'提交结果待核对'};
