 if(action==='review')return showModal('保存设计检查记录','这不是实物安全认证。请检查实际文件，而不只是屏幕预览。',`<form id="review-form" data-id="${id}"><div class="notice mb">至少核对中心开孔、夹持厚度、悬空部件、薄壁和材料限制。未确认的问题要写入记录。</div><div class="field"><label>本次检查结果</label><textarea name="note" required minlength="8" placeholder="例如：数字网格闭合；安装孔尺寸已核对。材料温升与 NFC 读距等待实测。"></textarea></div><label class="check"><input type="checkbox" name="acknowledge" required>我理解此记录不代表打印完成、实物验证通过或产品安全认证。</label><div class="modal-actions"><button class="btn" type="submit">保存检查记录</button></div></form>`);
