 if(action==='copy-secret'){await navigator.clipboard.writeText($('#device-secret').value);return toast('设备凭据已复制，请勿公开');}
 if(action==='guide')return showModal('把一段生活，变成一束光','SUNNY / The Growing Sunflower Lamp',`<div class="stack modal-copy"><p><strong>第一步：</strong>在「成长记忆」保存一段经历，再主动整理愿意发送的视觉描述。</p><p><strong>第二步：</strong>在「外装工作室」生成外装。默认是可离线运行的参数化演示；配置密钥后可选择真实 Tripo。</p><p><strong>第三步：</strong>检查设计并导出制造包，在 HeyGears Blueprint 中人工切片、打印和后处理。</p><p><strong>第四步：</strong>创建实体档案、绑定 NFC、装回台灯。没有硬件时可以走明确标记的模拟通道。</p><p><strong>第五步：</strong>发布设计，切换到另一个账号，在「交换花园」继续创作。</p><div class="notice">项目完整说明见 ZIP 根目录 README.md。图片上传需要安装 requirements.txt；硬件需要采购、烧录和打样。</div></div>`);
